// Appends Haircutting ids 232-262 and Chemical Waving & Relaxing ids 263-281
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

function fmt(q, topic, topic_es, psi_topic, psi_topic_es) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${psi_topic}, psi_topic_es: ${psi_topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

// ─── Last 31 Haircutting questions (ids 232–262) ─────────────────────────────
const hcTopic = [`"Haircutting & Hair Styling"`, `"Corte de Cabello y Peinado"`, `"Haircutting & Hair Styling"`, `"Corte de Cabello y Peinado"`]
const hcQ = [
  { id: 232, question: "Before draping a client for a haircut, the barber should first:", question_es: "Antes de cubrir al cliente para un corte de cabello, el barbero primero debe:", options: ["Place a clean neck strip around the client's neck before applying the cape", "Apply the cape directly against the client's skin", "Ask the client to hold the cape at the front", "Tuck the cape into the client's collar"], options_es: ["Colocar una tira de cuello limpia alrededor del cuello del cliente antes de aplicar la capa", "Aplicar la capa directamente contra la piel del cliente", "Pedir al cliente que sostenga la capa en la parte delantera", "Meter la capa en el cuello del cliente"], correct: 0, explanation: "A neck strip (neck tissue) must be placed around the client's neck before the cape is applied. This prevents the cape from touching the client's skin directly, maintaining sanitation and client comfort." },
  { id: 233, question: "The barber chair should be adjusted so that:", question_es: "La silla de barbería debe ajustarse para que:", options: ["The client's head is at a comfortable working height for the barber — approximately the barber's chest or upper abdomen level", "The chair is always at its lowest setting to ensure stability", "The client's feet are flat on the floor at all times", "The back of the chair is fully reclined for all services"], options_es: ["La cabeza del cliente esté a una altura de trabajo cómoda para el barbero — aproximadamente al nivel del pecho o abdomen superior del barbero", "La silla esté siempre en su ajuste más bajo para garantizar la estabilidad", "Los pies del cliente estén planos en el suelo en todo momento", "El respaldo de la silla esté completamente reclinado para todos los servicios"], correct: 0, explanation: "Adjusting the chair height so the client's head is at working height prevents the barber from bending or reaching excessively, reducing fatigue and ergonomic injury risk over a full day of services." },
  { id: 234, question: "After a haircut is complete, hair clippings on the client should be removed using:", question_es: "Después de que se complete un corte de cabello, los cabellos cortados en el cliente deben eliminarse usando:", options: ["A clean neck duster brush — not a reused or shared brush — to brush clippings from the neck and face", "The barber's hand to wipe clippings away", "A used towel left on the counter", "A hand-held blow dryer only"], options_es: ["Un cepillo para el cuello limpio — no un cepillo reutilizado o compartido — para cepillar los cabellos del cuello y el rostro", "La mano del barbero para limpiar los cabellos", "Una toalla usada dejada en el mostrador", "Solo un secador de mano"], correct: 0, explanation: "A neck duster brush removes hair clippings from the client's neck and face after the cut. The brush must be clean (or single-use) — a shared brush that contacts multiple clients without disinfection is a sanitation violation." },
  { id: 235, question: "Androgenic alopecia (male pattern baldness) is characterized by:", question_es: "La alopecia androgénica (calvicie de patrón masculino) se caracteriza por:", options: ["Progressive hair thinning at the temples and crown, following the Norwood-Hamilton scale pattern", "Sudden patchy hair loss in circular bald spots", "Hair loss due to excessive tension from tight hairstyles", "Complete total hair loss across the entire scalp"], options_es: ["Adelgazamiento progresivo del cabello en las sienes y la coronilla, siguiendo el patrón de la escala Norwood-Hamilton", "Pérdida repentina de cabello en manchas circulares calvas", "Pérdida de cabello debido a la tensión excesiva de peinados apretados", "Pérdida total completa del cabello en todo el cuero cabelludo"], correct: 0, explanation: "Androgenic alopecia (male pattern baldness) is a genetic, hormone-influenced condition causing progressive thinning. The Norwood-Hamilton scale classifies it in stages from slight recession to complete top baldness." },
  { id: 236, question: "Alopecia areata is characterized by:", question_es: "La alopecia areata se caracteriza por:", options: ["Sudden, patchy, coin-shaped areas of hair loss, usually caused by an autoimmune reaction", "Gradual thinning starting at the crown (male pattern)", "Hair loss caused by fungal infection of the scalp", "Complete hair loss on the entire body"], options_es: ["Pérdida de cabello repentina y en parches en forma de moneda, generalmente causada por una reacción autoinmune", "Adelgazamiento gradual que comienza en la coronilla (patrón masculino)", "Pérdida de cabello causada por infección fúngica del cuero cabelludo", "Pérdida total de cabello en todo el cuerpo"], correct: 0, explanation: "Alopecia areata is an autoimmune condition where the body attacks hair follicles, causing sudden, round or oval patches of hair loss. It is not contagious. Service may be performed, but the cause must be confirmed (not a fungal infection like tinea)." },
  { id: 237, question: "Traction alopecia results from:", question_es: "La alopecia por tracción resulta de:", options: ["Repeated, prolonged tension on the hair from tight braids, ponytails, locs, or extensions pulling on the follicle", "A fungal infection of the scalp", "An autoimmune reaction causing follicle attack", "Chemical damage to the hair cortex"], options_es: ["Tensión repetida y prolongada en el cabello de trenzas apretadas, coletas, locs o extensiones que jalan el folículo", "Una infección fúngica del cuero cabelludo", "Una reacción autoinmune que causa ataque al folículo", "Daño químico al córtex del cabello"], correct: 0, explanation: "Traction alopecia occurs when persistent mechanical tension on the hair pulls follicles, progressively damaging them. If caught early, hair can regrow when tension is relieved; chronic traction can cause permanent follicle damage." },
  { id: 238, question: "When cutting hair around the ears, the barber should:", question_es: "Al cortar el cabello alrededor de las orejas, el barbero debe:", options: ["Fold the ear gently forward with the non-cutting hand to expose the hair behind the ear and protect the ear from the clippers", "Leave the ear area until last and cut around it without touching the ear", "Ask the client to hold their ear forward during the service", "Skip close work around the ear and fade the area only"], options_es: ["Doblar la oreja suavemente hacia adelante con la mano que no corta para exponer el cabello detrás de la oreja y proteger la oreja de las cortadoras", "Dejar el área de la oreja hasta el final y cortar alrededor sin tocar la oreja", "Pedir al cliente que sostenga la oreja hacia adelante durante el servicio", "Omitir el trabajo cercano alrededor de la oreja y solo desvanecerla"], correct: 0, explanation: "Folding the ear gently forward with the free hand exposes the hair behind and above the ear, allowing close clipper work without nicking the ear. The hand also protects the ear from direct clipper contact." },
  { id: 239, question: "A client with very fine, thinning hair should generally receive:", question_es: "Un cliente con cabello muy fino y ralo generalmente debe recibir:", options: ["A haircut that adds the appearance of volume, such as a blunt perimeter and layering that creates lift, while avoiding very short styles that expose the scalp", "A skin fade to minimize the contrast between thin areas", "The shortest possible cut to reduce the visibility of thinning", "A razor cut to thin the hair further and reduce weight"], options_es: ["Un corte de cabello que añada apariencia de volumen, como un perímetro recto y capas que crean elevación, evitando estilos muy cortos que exponen el cuero cabelludo", "Un degradé al ras para minimizar el contraste entre las áreas delgadas", "El corte más corto posible para reducir la visibilidad del adelgazamiento", "Un corte con navaja para adelgazar aún más el cabello y reducir el peso"], correct: 0, explanation: "Fine, thinning hair benefits from blunt perimeters (which make hair look thicker), gentle layering to create lift, and product. Very short cuts and skin fades can expose scalp and emphasize thinning." },
  { id: 240, question: "When performing a scissor cut on wet hair, the barber must be aware that:", question_es: "Al realizar un corte con tijeras en cabello húmedo, el barbero debe estar consciente de que:", options: ["Wet hair stretches and will appear shorter than expected once it dries, especially on wavy or curly hair", "Wet hair should be cut longer than desired to compensate for drying shrinkage", "Wet hair produces a blunter result than dry cutting", "Wet hair should never be cut with scissors"], options_es: ["El cabello húmedo se estira y parecerá más corto de lo esperado una vez que se seca, especialmente en cabello ondulado o rizado", "El cabello húmedo debe cortarse más largo de lo deseado para compensar la contracción al secar", "El cabello húmedo produce un resultado más recto que el corte en seco", "El cabello húmedo nunca debe cortarse con tijeras"], correct: 0, explanation: "Wet hair stretches under tension, so it appears longer when combed wet than when dry. On wavy or curly hair, drying brings the hair up significantly. Barbers must account for this 'spring factor' — particularly on curly hair." },
  { id: 241, question: "After completing a haircut, the barber should perform a final visual check by:", question_es: "Después de completar un corte de cabello, el barbero debe realizar una verificación visual final:", options: ["Having the client look in the mirror and viewing the cut from the front, sides, and back to confirm evenness and symmetry", "Combing the hair one final time from front to back", "Applying finishing product and brushing the hair down", "Asking the client if they are satisfied without visual inspection"], options_es: ["Haciendo que el cliente se mire en el espejo y viendo el corte desde el frente, los lados y la parte posterior para confirmar la uniformidad y la simetría", "Peinando el cabello una última vez de frente a atrás", "Aplicando producto de acabado y cepillando el cabello hacia abajo", "Preguntando al cliente si está satisfecho sin inspección visual"], correct: 0, explanation: "A final inspection from multiple angles (front, both sides, back) confirms symmetry, evenness, and that the cut matches the client's consultation request. Using a hand mirror to show the client the back is standard professional practice." },
  { id: 242, question: "Proper handling of scissors includes:", question_es: "El manejo adecuado de las tijeras incluye:", options: ["Palming (holding scissors in the palm) when not actively cutting so they are out of the way but still in hand", "Setting scissors on the counter between every cut", "Keeping scissors open and pointing outward when not cutting", "Passing scissors to another barber by the blade end"], options_es: ["Sostener las tijeras en la palma cuando no se está cortando activamente para que estén fuera del camino pero aún en la mano", "Poner las tijeras en el mostrador entre cada corte", "Mantener las tijeras abiertas y apuntando hacia afuera cuando no se está cortando", "Pasar las tijeras a otro barbero por el extremo de la hoja"], correct: 0, explanation: "Palming scissors (holding them in the palm with ring finger removed from the ring) keeps them safely in hand and out of the way during combing. Open scissors pointing outward create a safety hazard." },
  { id: 243, question: "A 'corrective haircut' is performed when:", question_es: "Un 'corte de cabello correctivo' se realiza cuando:", options: ["A previous haircut has uneven lengths, incorrect layering, or other issues that the barber must fix", "A client wants to change their style completely", "A chemical service has damaged the hair and must be trimmed", "The barber is training a new technique on a mannequin"], options_es: ["Un corte de cabello anterior tiene longitudes desiguales, capas incorrectas u otros problemas que el barbero debe corregir", "Un cliente quiere cambiar su estilo completamente", "Un servicio químico ha dañado el cabello y debe recortarse", "El barbero está entrenando una nueva técnica en un maniquí"], correct: 0, explanation: "A corrective haircut addresses problems from a previous cut — uneven lengths, misaligned fade lines, incorrect graduation, etc. It requires careful consultation to identify the problem and an appropriate strategy to correct it." },
  { id: 244, question: "The purpose of the barber consultation card (client record card) is:", question_es: "El propósito de la tarjeta de consulta del barbero (tarjeta de registro del cliente) es:", options: ["To document the client's hair characteristics, services performed, products used, and any sensitivities or preferences for reference in future visits", "To track financial transactions with clients", "To record TDLR inspection results", "To document the barber's own training and education"], options_es: ["Documentar las características del cabello del cliente, los servicios realizados, los productos usados y cualquier sensibilidad o preferencia para referencia en visitas futuras", "Rastrear transacciones financieras con los clientes", "Registrar los resultados de inspección de TDLR", "Documentar la formación y educación del propio barbero"], correct: 0, explanation: "Client record cards document hair analysis results, services performed, products used, processing times, and any allergies or reactions. This information ensures consistent, safe service during every visit." },
  { id: 245, question: "Which of the following is true about working with hair that has a prominent cowlick?", question_es: "¿Cuál de las siguientes afirmaciones es verdadera acerca de trabajar con cabello que tiene un remolino prominente?", options: ["The cowlick area should be cut slightly longer to allow the hair to lie flat; cutting too short makes it stand up more", "Cowlick hair should always be cut shorter than surrounding hair to lie flat", "A cowlick can be eliminated by cutting the hair very close to the scalp", "Cowlicks are not relevant to the cutting technique used"], options_es: ["El área del remolino debe cortarse un poco más larga para que el cabello quede plano; cortarlo demasiado corto hace que se levante más", "El cabello del remolino siempre debe cortarse más corto que el cabello circundante para quedar plano", "Un remolino puede eliminarse cortando el cabello muy cerca del cuero cabelludo", "Los remolinos no son relevantes para la técnica de corte usada"], correct: 0, explanation: "Cowlick hair grows in a different direction — cutting it too short causes it to stand up prominently. Leaving it slightly longer allows gravity and the surrounding hair to weigh it down enough to lie flatter." },
  { id: 246, question: "Effilating scissors (single-sided thinning shears) remove bulk by:", question_es: "Las tijeras de effilé (tijeras de entresacado de un solo lado) eliminan el volumen mediante:", options: ["Cutting some strands while leaving others, depending on the tooth count — more teeth remove less bulk; fewer teeth remove more", "Cutting all strands in a section completely", "Sliding along the hair shaft without cutting any strands completely", "Using vibration to loosen and remove hair fibers"], options_es: ["Cortando algunas hebras mientras deja otras, dependiendo del número de dientes — más dientes eliminan menos volumen; menos dientes eliminan más", "Cortando completamente todas las hebras de una sección", "Deslizándose a lo largo del eje del cabello sin cortar completamente ninguna hebra", "Usando vibración para aflojar y eliminar las fibras del cabello"], correct: 0, explanation: "Thinning shears have one serrated blade. The teeth remove a percentage of hair with each cut, leaving the other strands at full length. Fewer teeth (wider spacing) remove more hair per stroke; more teeth remove less — offering more controlled thinning." },
  { id: 247, question: "The 'spine' (back of the blade) of the scissors should face:", question_es: "La 'espina' (parte posterior de la hoja) de las tijeras debe mirar hacia:", options: ["The barber's palm, allowing the blades to face the hair with cutting edges forward", "Outward away from the hair", "Toward the client's scalp", "Upward toward the ceiling during all cuts"], options_es: ["La palma del barbero, permitiendo que las hojas enfrenten el cabello con los bordes de corte hacia adelante", "Hacia afuera lejos del cabello", "Hacia el cuero cabelludo del cliente", "Hacia el techo durante todos los cortes"], correct: 0, explanation: "The spine (back) of the scissors faces the palm of the barber's hand during normal cutting, with the sharp cutting edges facing the hair section being cut. This is the standard grip for control and safety." },
  { id: 248, question: "What is the purpose of a 'bang trim' (fringe trim) service?", question_es: "¿Cuál es el propósito de un servicio de 'recorte de flequillo'?", options: ["To remove excess length from the front fringe of hair that has grown below the desired length", "To add volume to flat front hair", "To layer the hair starting at the forehead hairline", "To create a widow's peak shape at the forehead"], options_es: ["Eliminar el exceso de longitud del flequillo frontal del cabello que ha crecido más allá de la longitud deseada", "Añadir volumen al cabello plano del frente", "Hacer capas en el cabello comenzando en la línea del cabello de la frente", "Crear una forma de pico de viuda en la frente"], correct: 0, explanation: "A bang (fringe) trim is a maintenance service that trims the front section of hair that hangs over the forehead back to the client's preferred length. It is a quick service that keeps the style looking fresh between full haircuts." },
  { id: 249, question: "When a barber notices scalp scaling, redness, and itching during a service, the most appropriate action is:", question_es: "Cuando un barbero nota descamación del cuero cabelludo, enrojecimiento y picazón durante un servicio, la acción más apropiada es:", options: ["Note the condition, avoid irritating the scalp during the service, and recommend the client consult a dermatologist if the condition persists", "Apply antiseptic lotion to the scalp immediately", "Proceed with the service and recommend a dandruff shampoo", "Refuse service and ask the client to leave"], options_es: ["Anotar la condición, evitar irritar el cuero cabelludo durante el servicio y recomendar al cliente consultar a un dermatólogo si la condición persiste", "Aplicar loción antiséptica en el cuero cabelludo inmediatamente", "Continuar el servicio y recomendar un champú anticaspa", "Rechazar el servicio y pedir al cliente que se vaya"], correct: 0, explanation: "If a non-contagious scalp condition (like seborrheic dermatitis or psoriasis) is observed, the barber can proceed with care, avoid irritating the scalp, and professionally recommend a dermatologist visit. If contagion is suspected, service must be refused." },
  { id: 250, question: "Hair porosity can be tested by:", question_es: "La porosidad del cabello se puede probar mediante:", options: ["Sliding a few strands between the fingers from tip to root — if it feels rough or bumpy, porosity is high; smooth means low porosity", "Pulling a wet strand to see how far it stretches", "Counting the number of visible split ends", "Applying heat to a small section to observe how quickly it dries"], options_es: ["Deslizar algunas hebras entre los dedos de la punta a la raíz — si se siente áspero o con protuberancias, la porosidad es alta; liso significa baja porosidad", "Jalar una hebra húmeda para ver cuánto se estira", "Contar el número de puntas abiertas visibles", "Aplicar calor a una pequeña sección para observar qué tan rápido se seca"], correct: 0, explanation: "The porosity test involves sliding fingers from tip to root — rough/bumpy cuticle scales indicate high (damaged) porosity; a smooth feel indicates low porosity (tight cuticle). This helps determine product needs and chemical service suitability." },
  { id: 251, question: "Hair elasticity is tested by:", question_es: "La elasticidad del cabello se prueba mediante:", options: ["Gently stretching a single wet hair strand — normal elasticity stretches 40–50% before breaking; poor elasticity breaks with minimal stretch", "Running a comb through the hair to feel resistance", "Applying water and observing how quickly it absorbs", "Pulling a dry strand from root to tip between two fingers"], options_es: ["Estirar suavemente una sola hebra de cabello húmedo — la elasticidad normal se estira un 40–50% antes de romperse; la elasticidad deficiente se rompe con un estiramiento mínimo", "Pasar un peine por el cabello para sentir la resistencia", "Aplicar agua y observar qué tan rápido se absorbe", "Jalar una hebra seca de raíz a punta entre dos dedos"], correct: 0, explanation: "A wet hair strand with good elasticity can stretch 40-50% before breaking and returns to its original length. Poor elasticity (damaged cortex) causes the strand to break with minimal stretch — a warning sign before chemical services." },
  { id: 252, question: "Professional barber ethics during a client consultation include:", question_es: "La ética profesional del barbero durante una consulta con el cliente incluye:", options: ["Listening carefully to the client's requests, providing honest professional recommendations, and respecting the client's final decision", "Always recommending the most expensive service available", "Performing only the service that the barber prefers, not what the client requests", "Sharing opinions about the client's previous barber's work"], options_es: ["Escuchar atentamente las solicitudes del cliente, brindar recomendaciones profesionales honestas y respetar la decisión final del cliente", "Siempre recomendar el servicio más caro disponible", "Realizar solo el servicio que el barbero prefiere, no lo que el cliente solicita", "Compartir opiniones sobre el trabajo del barbero anterior del cliente"], correct: 0, explanation: "Professional ethics require active listening, honest and knowledgeable recommendations, and ultimately respecting the client's wishes. Disparaging a previous barber's work or pressuring clients toward expensive services is unprofessional." },
  { id: 253, question: "Why is the mirror used during and after a haircut?", question_es: "¿Por qué se usa el espejo durante y después de un corte de cabello?", options: ["To allow the client to see their reflection and provide real-time feedback; and for the barber to check symmetry and balance throughout the cut", "Only to show the client the finished result at the end", "To reflect light onto the work area for better visibility", "To check the barber's own appearance during the service"], options_es: ["Para permitir que el cliente vea su reflejo y proporcione retroalimentación en tiempo real; y para que el barbero verifique la simetría y el equilibrio durante todo el corte", "Solo para mostrar al cliente el resultado final al final", "Para reflejar la luz en el área de trabajo para mejor visibilidad", "Para verificar la apariencia propia del barbero durante el servicio"], correct: 0, explanation: "The mirror serves two functions: it allows the client to give feedback during the haircut, and it gives the barber a broader view to check for symmetry, balance, and evenness at different points during the service." },
  { id: 254, question: "The correct way to hold the comb when performing clipper-over-comb is:", question_es: "La forma correcta de sostener el peine al realizar cortadora sobre peine es:", options: ["Comb held parallel to the head, teeth pointing outward from the scalp at the desired angle, lifting the hair at the correct length for the clipper to cut", "Comb held vertically with teeth pointing downward at all times", "Comb held at 90 degrees perpendicular to the scalp in all areas", "Comb hidden behind the clipper blade to avoid interference"], options_es: ["Peine sostenido paralelo a la cabeza, dientes apuntando hacia afuera del cuero cabelludo en el ángulo deseado, levantando el cabello a la longitud correcta para que la cortadora corte", "Peine sostenido verticalmente con dientes apuntando hacia abajo en todo momento", "Peine sostenido a 90 grados perpendicular al cuero cabelludo en todas las áreas", "Peine escondido detrás de la cuchilla de la cortadora para evitar interferencias"], correct: 0, explanation: "In clipper-over-comb, the comb lifts the hair at the desired angle and length while the clipper follows along the comb's spine, cutting the hair that extends above it. Correct comb angle determines the graduation of the blend." },
  { id: 255, question: "Hair loss at the temples (bitemporal recession) in men is:", question_es: "La pérdida de cabello en las sienes (recesión bitemporal) en los hombres es:", options: ["Typically the first sign of androgenic alopecia (male pattern baldness), classified as Stage II on the Norwood-Hamilton scale", "Always caused by nutritional deficiency", "A sign of alopecia areata requiring medical treatment", "Only cosmetically relevant and not related to any underlying condition"], options_es: ["Típicamente el primer signo de alopecia androgénica (calvicie de patrón masculino), clasificada como Etapa II en la escala Norwood-Hamilton", "Siempre causada por deficiencia nutricional", "Una señal de alopecia areata que requiere tratamiento médico", "Solo cosméticamente relevante y no relacionada con ninguna condición subyacente"], correct: 0, explanation: "Bitemporal recession (the hairline receding at the temples forming an 'M' shape) is typically the first visible stage of male pattern baldness (androgenic alopecia), classified as Stage II on the Norwood-Hamilton scale." },
  { id: 256, question: "A clipper should be moved in which direction during a standard blending pass?", question_es: "¿En qué dirección debe moverse una cortadora durante un pase estándar de mezcla?", options: ["Against the direction of hair growth, moving upward and outward from the head with a scooping motion", "With the direction of hair growth for a smoother finish", "In a horizontal pass only from front to back", "In a downward motion only, cutting from top to bottom"], options_es: ["Contra la dirección del crecimiento del cabello, moviéndose hacia arriba y hacia afuera de la cabeza con un movimiento de cuchareo", "A favor de la dirección del crecimiento del cabello para un acabado más suave", "Solo en un pase horizontal de frente a atrás", "Solo en un movimiento hacia abajo, cortando de arriba hacia abajo"], correct: 0, explanation: "For most blending passes, the clipper moves against the direction of hair growth (upward) so the hair is lifted into the blades. A scooping or flicking wrist motion at the end of each pass softens the line." },
  { id: 257, question: "When a client requests 'just a trim,' the barber should:", question_es: "Cuando un cliente solicita 'solo un recorte', el barbero debe:", options: ["Ask the client to specify exactly how much length to remove, since 'a trim' means different amounts to different clients", "Remove approximately 1 inch uniformly all over", "Clean up the neckline and around the ears without removing any length", "Remove as little hair as possible to satisfy the request"], options_es: ["Pedir al cliente que especifique exactamente cuánta longitud eliminar, ya que 'un recorte' significa diferentes cantidades para diferentes clientes", "Eliminar aproximadamente 1 pulgada uniformemente en todo el cabello", "Limpiar la línea del cuello y alrededor de las orejas sin eliminar ninguna longitud", "Eliminar la menor cantidad de cabello posible para satisfacer la solicitud"], correct: 0, explanation: "The phrase 'just a trim' is vague. Professional practice requires clarifying exactly how much the client wants removed (show with fingers, reference a previous length). Assuming the amount leads to client dissatisfaction." },
  { id: 258, question: "When sectioning the hair for a blunt one-length cut on medium-length hair, which direction should sections be taken?", question_es: "Al seccionar el cabello para un corte recto de un solo largo en cabello de longitud media, ¿en qué dirección deben tomarse las secciones?", options: ["Horizontal sections, working from the nape upward", "Vertical sections from left to right", "Diagonal sections from front to back", "Radial sections from the crown outward"], options_es: ["Secciones horizontales, trabajando desde la nuca hacia arriba", "Secciones verticales de izquierda a derecha", "Secciones diagonales de frente a atrás", "Secciones radiales desde la coronilla hacia afuera"], correct: 0, explanation: "A blunt (one-length) cut uses horizontal sections taken from the nape upward. Each section is combed down and cut to match the guide below it, creating an even, single perimeter length throughout." },
  { id: 259, question: "Point cutting should not be performed too close to the scalp because:", question_es: "El corte en punta no debe realizarse demasiado cerca del cuero cabelludo porque:", options: ["The open scissor tips pose a safety risk of poking or scratching the client's scalp", "It removes too much length from the interior", "It causes the hair to frizz when it dries", "It creates too much weight at the roots"], options_es: ["Las puntas abiertas de las tijeras representan un riesgo de seguridad de pinchar o rasguñar el cuero cabelludo del cliente", "Elimina demasiada longitud del interior", "Hace que el cabello se encrespe cuando se seca", "Crea demasiado peso en las raíces"], correct: 0, explanation: "Point cutting near the scalp risks the open tips of the scissors contacting and injuring the scalp. This technique is best used on mid-shaft to ends, not close to the root area." },
  { id: 260, question: "During a consultation, the barber should visually analyze the client's head shape to:", question_es: "Durante una consulta, el barbero debe analizar visualmente la forma de la cabeza del cliente para:", options: ["Identify any flat spots, bumps, or asymmetries that will affect how the cut lays and appears on the client", "Determine whether a chemical service is needed", "Assess the client's scalp health for infection control", "Measure the exact length of existing hair sections"], options_es: ["Identificar cualquier punto plano, protuberancia o asimetría que afectará cómo queda y se ve el corte en el cliente", "Determinar si se necesita un servicio químico", "Evaluar la salud del cuero cabelludo del cliente para el control de infecciones", "Medir la longitud exacta de las secciones de cabello existentes"], correct: 0, explanation: "Head shape analysis helps the barber understand how the cut will lay on that specific head. Flat spots, wide occipital bones, or asymmetries affect where weight builds and how the finished style looks." },
  { id: 261, question: "Which professional tool maintenance practice protects the investment in quality haircutting scissors?", question_es: "¿Qué práctica de mantenimiento de herramientas profesionales protege la inversión en tijeras de corte de cabello de calidad?", options: ["Having scissors professionally sharpened by a qualified scissors technician when needed, and properly cleaning and storing after each use", "Sharpening scissors with a kitchen knife sharpener weekly", "Cleaning scissors only when visibly dirty", "Storing scissors open in a container with other tools"], options_es: ["Llevar las tijeras a afilar profesionalmente por un técnico de tijeras calificado cuando sea necesario, y limpiar y almacenar adecuadamente después de cada uso", "Afilar las tijeras con un afilador de cuchillos de cocina semanalmente", "Limpiar las tijeras solo cuando estén visiblemente sucias", "Almacenar las tijeras abiertas en un recipiente con otras herramientas"], correct: 0, explanation: "Quality shears require professional sharpening by a licensed scissors technician — home sharpening devices damage the precision blade geometry. Proper cleaning, disinfection, oiling the pivot, and individual storage (case or pouch) extend scissor life." },
  { id: 262, question: "A barber who consistently uses the same guide when cutting all sections of a haircut will produce:", question_es: "Un barbero que consistentemente usa la misma guía al cortar todas las secciones de un corte de cabello producirá:", options: ["A one-length or uniformly layered result depending on where hair is directed (a stationary guide creates one-length; traveling guide creates layers)", "A graduated or stacked cut regardless of technique", "A random, unpredictable length variation", "Always a blunt perimeter cut with no layering"], options_es: ["Un resultado de un solo largo o con capas uniformes dependiendo de hacia dónde se dirige el cabello (una guía estacionaria crea un solo largo; una guía de viaje crea capas)", "Un corte graduado o apilado independientemente de la técnica", "Una variación aleatoria e impredecible de la longitud", "Siempre un corte de perímetro recto sin capas"], correct: 0, explanation: "A stationary guide (all hair brought to one fixed point and cut) creates one length. A traveling guide (each cut section becomes the next guide, progressively moving) creates layers. Both use consistent guides but for different purposes." },
]

// ─── First 19 Chemical Waving & Relaxing questions (ids 263–281) ──────────────
const cwTopic = [`"Chemical Waving & Relaxing"`, `"Ondulación Química y Alisado"`, `"Chemical Waving & Relaxing"`, `"Ondulación Química y Alisado"`]
const cwQ = [
  { id: 263, question: "The active ingredient in most permanent wave (perm) solutions is:", question_es: "El ingrediente activo en la mayoría de las soluciones de permanente es:", options: ["Ammonium thioglycolate (ATG)", "Sodium hydroxide", "Hydrogen peroxide", "Guanidine carbonate"], options_es: ["Tioglicolato de amonio (ATG)", "Hidróxido de sodio", "Peróxido de hidrógeno", "Carbonato de guanidina"], correct: 0, explanation: "Ammonium thioglycolate (ATG) is the reducing agent in most thio-based perm solutions. It breaks the disulfide bonds in the hair cortex, allowing hair to conform to the shape of the perm rod." },
  { id: 264, question: "The two-step process of a permanent wave involves:", question_es: "El proceso de dos pasos de una permanente implica:", options: ["Reducing (breaking disulfide bonds with perm solution) and then oxidizing (reforming bonds with neutralizer)", "Cleaning and conditioning the hair before waving", "Applying base and then applying activator", "Wetting the hair and then applying heat to set the curl"], options_es: ["Reducción (rompiendo enlaces disulfuro con la solución de permanente) y luego oxidación (reformando enlaces con el neutralizante)", "Limpiar y acondicionar el cabello antes de ondular", "Aplicar base y luego aplicar activador", "Mojar el cabello y luego aplicar calor para fijar el rizo"], correct: 0, explanation: "Permanent waving uses a two-step chemical process: (1) the waving lotion (reducing agent — usually ATG) softens and breaks disulfide bonds; (2) the neutralizer (oxidizing agent — usually hydrogen peroxide) reforms the bonds in the new waved shape." },
  { id: 265, question: "The neutralizer used in permanent waving is typically:", question_es: "El neutralizante usado en la permanente es típicamente:", options: ["Hydrogen peroxide (an oxidizer) that reforms disulfide bonds in the new curled position", "Ammonium thioglycolate to stop the waving process", "Sodium hydroxide to stabilize the curl", "Distilled water to rinse out the wave solution"], options_es: ["Peróxido de hidrógeno (un oxidante) que reforma los enlaces disulfuro en la nueva posición rizada", "Tioglicolato de amonio para detener el proceso de ondulación", "Hidróxido de sodio para estabilizar el rizo", "Agua destilada para enjuagar la solución de ondulación"], correct: 0, explanation: "Perm neutralizers typically contain hydrogen peroxide (usually 3-5%) which oxidizes (re-forms) the disulfide bonds that were broken by the waving lotion. This locks the hair into its new curled shape permanently." },
  { id: 266, question: "Which type of relaxer contains sodium hydroxide (lye) as its active ingredient?", question_es: "¿Qué tipo de relajador contiene hidróxido de sodio (lejía) como ingrediente activo?", options: ["Lye (sodium hydroxide) relaxer", "No-lye relaxer (guanidine-based)", "Thio relaxer (ammonium thioglycolate)", "Acid-balanced relaxer"], options_es: ["Relajador de lejía (hidróxido de sodio)", "Relajador sin lejía (base de guanidina)", "Relajador thio (tioglicolato de amonio)", "Relajador equilibrado en ácido"], correct: 0, explanation: "Lye relaxers contain sodium hydroxide (NaOH) as the active ingredient. They have a high pH (around 12-14) and break the disulfide bonds through a process called lanthionization, permanently straightening the hair." },
  { id: 267, question: "No-lye relaxers differ from lye relaxers in that no-lye relaxers:", question_es: "Los relajadores sin lejía difieren de los relajadores con lejía en que los relajadores sin lejía:", options: ["Use alternative hydroxides (calcium or potassium hydroxide mixed with guanidine carbonate) rather than sodium hydroxide, and tend to be milder on the scalp", "Are less effective and do not permanently straighten hair", "Have a lower pH than lye relaxers, making them acidic", "Are recommended exclusively for fine, color-treated hair"], options_es: ["Usan hidróxidos alternativos (hidróxido de calcio o de potasio mezclado con carbonato de guanidina) en lugar de hidróxido de sodio, y tienden a ser más suaves en el cuero cabelludo", "Son menos efectivos y no alisan el cabello permanentemente", "Tienen un pH más bajo que los relajadores con lejía, haciéndolos ácidos", "Se recomiendan exclusivamente para cabello fino tratado con color"], correct: 0, explanation: "No-lye relaxers use guanidine hydroxide (formed by mixing calcium or potassium hydroxide with guanidine carbonate). They tend to cause less scalp irritation than lye relaxers but can leave more calcium buildup on the hair shaft." },
  { id: 268, question: "Before applying a chemical relaxer, the barber/stylist should perform a:", question_es: "Antes de aplicar un relajador químico, el barbero/estilista debe realizar una:", options: ["Skin patch test (allergy test) 24–48 hours before the service", "Strand test immediately before application", "Hair density assessment only", "Elasticity test after shampooing"], options_es: ["Prueba de parche en la piel (prueba de alergia) 24–48 horas antes del servicio", "Prueba de mechón inmediatamente antes de la aplicación", "Solo evaluación de densidad del cabello", "Prueba de elasticidad después del champú"], correct: 0, explanation: "A patch (allergy) test should be performed 24-48 hours before any chemical service to identify allergic reactions to the chemicals. A strand test assesses hair integrity and is done as a processing test during the service." },
  { id: 269, question: "A 'base' relaxer application means:", question_es: "Una aplicación de relajador 'con base' significa:", options: ["A protective cream (base) is applied to the scalp before the relaxer is applied to protect the skin from the caustic chemicals", "The relaxer is applied starting at the base (root) of the hair", "Only the base formulation of the relaxer is used without activator", "A pre-shampoo base treatment is applied to the hair shaft"], options_es: ["Se aplica una crema protectora (base) en el cuero cabelludo antes de aplicar el relajador para proteger la piel de los químicos cáusticos", "El relajador se aplica comenzando en la base (raíz) del cabello", "Solo se usa la formulación base del relajador sin activador", "Se aplica un tratamiento base de pre-champú en el eje del cabello"], correct: 0, explanation: "A 'base' relaxer application includes applying a protective cream (petrolatum or similar) to the scalp, hairline, and ears before the relaxer. This base protects skin from chemical burns caused by the highly alkaline relaxer." },
  { id: 270, question: "Over-processing a relaxer results in:", question_es: "El sobreprocesamiento de un relajador resulta en:", options: ["Severely damaged hair — breakage, extreme brittleness, and chemical burns — because the disulfide bonds are over-softened", "A tighter curl pattern being created", "Hair that holds the style better than properly processed hair", "The relaxer stopping its action automatically at the correct point"], options_es: ["Cabello severamente dañado — rotura, fragilidad extrema y quemaduras químicas — porque los enlaces disulfuro están excesivamente suavizados", "Creación de un patrón de rizo más apretado", "Cabello que mantiene el estilo mejor que el cabello procesado correctamente", "El relajador detiene su acción automáticamente en el punto correcto"], correct: 0, explanation: "Over-processing with a relaxer destroys too many disulfide bonds, leaving the hair extremely weak and brittle. The hair can break off, and the highly alkaline chemical left on the scalp too long can cause chemical burns." },
  { id: 271, question: "When applying a relaxer retouch, the product is applied:", question_es: "Al aplicar un retoque de relajador, el producto se aplica:", options: ["Only to the new growth (virgin hair at the roots), avoiding previously relaxed hair to prevent overlapping damage", "From the ends of the hair upward to the roots", "All over the hair including previously relaxed sections", "Starting at the ends and working to the midshaft only"], options_es: ["Solo al nuevo crecimiento (cabello virgen en las raíces), evitando el cabello previamente relajado para prevenir el daño por superposición", "Desde las puntas del cabello hacia arriba hasta las raíces", "En todo el cabello incluyendo las secciones previamente relajadas", "Comenzando en las puntas y trabajando solo hasta el punto medio"], correct: 0, explanation: "A relaxer retouch applies product ONLY to the new growth (regrowth) since the last service. Applying relaxer over previously relaxed hair causes 'overlapping' — double-processing that severely weakens and breaks the hair." },
  { id: 272, question: "The pH of lye (sodium hydroxide) relaxers is approximately:", question_es: "El pH de los relajadores de lejía (hidróxido de sodio) es aproximadamente:", options: ["12–14 (highly alkaline)", "7–8 (neutral to slightly alkaline)", "4–6 (acidic to slightly acidic)", "9–10 (mildly alkaline)"], options_es: ["12–14 (muy alcalino)", "7–8 (neutro a ligeramente alcalino)", "4–6 (ácido a ligeramente ácido)", "9–10 (ligeramente alcalino)"], correct: 0, explanation: "Lye relaxers (sodium hydroxide) have a very high pH of approximately 12-14, making them among the most caustic (alkaline) products used in cosmetology/barbering. This high alkalinity is what allows them to break down disulfide bonds." },
  { id: 273, question: "Thio relaxers (using ammonium thioglycolate) differ from hydroxide relaxers in that thio relaxers:", question_es: "Los relajadores thio (que usan tioglicolato de amonio) difieren de los relajadores de hidróxido en que los relajadores thio:", options: ["Work by reducing disulfide bonds (same process as perms) and can be followed by a neutralizer to reform bonds; hydroxide relaxers break bonds permanently without a neutralizer reforming them", "Are more alkaline than hydroxide relaxers", "Cannot straighten very curly hair types", "Use the same chemistry as hydroxide relaxers"], options_es: ["Funcionan reduciendo los enlaces disulfuro (el mismo proceso que las permanentes) y pueden ir seguidos de un neutralizante para reformar los enlaces; los relajadores de hidróxido rompen los enlaces permanentemente sin que un neutralizante los reforme", "Son más alcalinos que los relajadores de hidróxido", "No pueden alisar tipos de cabello muy rizados", "Usan la misma química que los relajadores de hidróxido"], correct: 0, explanation: "Thio relaxers are chemically similar to perms — they reduce (break) disulfide bonds using ATG and reform them with a neutralizer. Hydroxide relaxers break bonds through lanthionization, a one-way permanent change. You CANNOT perm over a hydroxide relaxer." },
  { id: 274, question: "A 'strand test' before chemical waving or relaxing is used to:", question_es: "Una 'prueba de mechón' antes de ondulación química o alisado se usa para:", options: ["Test how the hair responds to the chemical — checking processing time, curl result or straightening degree, and whether hair can withstand the service", "Check for allergic reaction on the skin", "Determine the client's hair density before the service", "Measure the amount of product needed for the entire head"], options_es: ["Probar cómo responde el cabello al químico — verificando el tiempo de procesamiento, el resultado del rizo o el grado de alisado, y si el cabello puede resistir el servicio", "Verificar la reacción alérgica en la piel", "Determinar la densidad del cabello del cliente antes del servicio", "Medir la cantidad de producto necesaria para toda la cabeza"], correct: 0, explanation: "A strand test is performed on a small section of hair (often from a hidden area) to determine how the hair responds to the chemical service — processing time needed, degree of straightening/curl achieved, and whether the hair is strong enough to withstand the service." },
  { id: 275, question: "Hair that has been previously relaxed with a hydroxide relaxer should NEVER be:", question_es: "El cabello que ha sido previamente relajado con un relajador de hidróxido NUNCA debe:", options: ["Permed with a thio (ammonium thioglycolate) perm solution, because the chemical processes are incompatible and will cause severe breakage", "Relaxed again with the same hydroxide product at a retouch appointment", "Washed with a chelating shampoo before chemical services", "Blow-dried before the next relaxer application"], options_es: ["Permanentado con una solución de permanente thio (tioglicolato de amonio), porque los procesos químicos son incompatibles y causarán rotura severa", "Relajado nuevamente con el mismo producto de hidróxido en una cita de retoque", "Lavado con un champú quelante antes de los servicios químicos", "Secado con secador antes de la siguiente aplicación de relajador"], correct: 0, explanation: "Hydroxide and thio relaxers use incompatible chemistry. Applying a thio perm over hydroxide-relaxed hair causes an adverse reaction that severely damages or destroys the hair. The client's chemical history must always be determined before any chemical service." },
  { id: 276, question: "Acid-balanced perms (true acid or acid-balanced waves) differ from alkaline perms in that they:", question_es: "Las permanentes de pH ácido equilibrado (verdaderas ácidas o de pH equilibrado) difieren de las permanentes alcalinas en que:", options: ["Have a lower pH (4.5–7.0), require heat to process, produce gentler results, and are better for fine, color-treated, or damaged hair", "Have a higher pH than alkaline perms and process faster", "Do not require a neutralizer after processing", "Cannot create a curl — only used for relaxing purposes"], options_es: ["Tienen un pH más bajo (4.5–7.0), requieren calor para procesar, producen resultados más suaves y son mejores para cabello fino, tratado con color o dañado", "Tienen un pH más alto que las permanentes alcalinas y procesan más rápido", "No requieren un neutralizante después del procesamiento", "No pueden crear un rizo — solo se usan para propósitos de alisado"], correct: 0, explanation: "Acid-balanced perms (pH 4.5-7.0) are gentler than alkaline perms (pH 8.5-9.5). They require heat (added or exothermic) to open the cuticle and process. They produce softer, more natural-looking curls and are better for chemically treated or fragile hair." },
  { id: 277, question: "A 'soft curl permanent' (reform permanent or curl reformation) is designed to:", question_es: "Una 'permanente de rizo suave' (reforma permanente o reformación de rizo) está diseñada para:", options: ["Loosen very tight natural coils into larger, softer curl patterns rather than completely straightening", "Add tight curls to straight hair", "Completely straighten all curl patterns to a bone-straight result", "Chemically remove color while reforming the curl"], options_es: ["Aflojar los rizos naturales muy apretados en patrones de rizo más grandes y suaves en lugar de alisar completamente", "Añadir rizos apretados al cabello liso", "Alisar completamente todos los patrones de rizo a un resultado completamente liso", "Eliminar químicamente el color mientras se reforma el rizo"], correct: 0, explanation: "A soft curl perm (curl reformation) is a two-step service (thio relaxer + perm rods + neutralizer) that converts very tight coils into a softer, looser curl pattern. It is popular for clients who want defined curls rather than straight hair." },
  { id: 278, question: "Protective cream (base cream) should be applied before a lye relaxer along:", question_es: "La crema protectora (crema base) debe aplicarse antes de un relajador de lejía a lo largo de:", options: ["The entire scalp, hairline, ears, and neck to protect skin from the caustic relaxer", "Only the hairline and ears", "Only the nape of the neck", "The mid-shaft of the hair only to protect processed ends"], options_es: ["Todo el cuero cabelludo, línea del cabello, orejas y cuello para proteger la piel del relajador cáustico", "Solo la línea del cabello y las orejas", "Solo la nuca del cuello", "Solo el punto medio del cabello para proteger las puntas procesadas"], correct: 0, explanation: "Base cream (petroleum jelly or similar protective cream) must be applied thoroughly to the entire scalp, hairline, ears, and neck before applying a lye relaxer. The highly alkaline relaxer can cause chemical burns on any unprotected skin." },
  { id: 279, question: "After a relaxer processing period, the relaxer is removed by:", question_es: "Después del período de procesamiento del relajador, el relajador se elimina mediante:", options: ["Thoroughly rinsing with warm water for 5–10 minutes before shampooing with a neutralizing shampoo to restore the hair's pH", "Wiping the relaxer off with dry towels", "Applying neutralizer directly without rinsing first", "Using cold water rinse only without shampooing"], options_es: ["Enjuagando a fondo con agua tibia durante 5–10 minutos antes de lavar con un champú neutralizante para restaurar el pH del cabello", "Limpiando el relajador con toallas secas", "Aplicar el neutralizante directamente sin enjuagar primero", "Usando solo enjuague de agua fría sin lavar"], correct: 0, explanation: "The relaxer must be thoroughly rinsed out with warm water first (for at least 5 minutes), then shampooed with a neutralizing (pH-balanced, acidic) shampoo to stop the chemical action and help restore the hair's natural pH." },
  { id: 280, question: "PPE required when applying chemical relaxers includes:", question_es: "El EPP requerido al aplicar relajadores químicos incluye:", options: ["Chemical-resistant gloves, protective apron, and eye protection", "Gloves only", "Mask and gloves but no eye protection needed for relaxers", "Gloves and lab coat but no eye protection"], options_es: ["Guantes resistentes a químicos, delantal protector y protección ocular", "Solo guantes", "Mascarilla y guantes pero no se necesita protección ocular para relajadores", "Guantes y bata de laboratorio pero sin protección ocular"], correct: 0, explanation: "When applying chemical relaxers, barbers/stylists must wear chemical-resistant gloves, a protective apron to prevent skin contact, and eye protection in case of splashing. Relaxers are highly caustic and can cause burns and eye damage." },
  { id: 281, question: "The term 'lanthionization' refers to:", question_es: "El término 'lantionización' se refiere a:", options: ["The permanent chemical change that occurs when a hydroxide relaxer breaks and converts disulfide bonds to lanthionine bonds, creating irreversible straightening", "The pH neutralization step after relaxer removal", "The process of applying protective base cream before relaxer application", "The pre-softening step in a soft curl perm service"], options_es: ["El cambio químico permanente que ocurre cuando un relajador de hidróxido rompe y convierte los enlaces disulfuro en enlaces de lantionina, creando un alisado irreversible", "El paso de neutralización del pH después de la eliminación del relajador", "El proceso de aplicar crema base protectora antes de la aplicación del relajador", "El paso de pre-suavizado en un servicio de permanente de rizo suave"], correct: 0, explanation: "Lanthionization is the irreversible chemical process in hydroxide relaxers: disulfide bonds (S-S) are converted to lanthionine bonds (S), permanently straightening the hair. This is why you CANNOT perm hair after a hydroxide relaxer." },
]

let out = readFileSync(FILE, 'utf8')
out += hcQ.map(q => fmt(q, ...hcTopic)).join('\n') + '\n'
out += '\n// ─── CHEMICAL WAVING & RELAXING (ids 263–336) ───────────────────────────────\n'
out += cwQ.map(q => fmt(q, ...cwTopic)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${hcQ.length} Haircutting (ids ${hcQ[0].id}–${hcQ[hcQ.length-1].id}) + ${cwQ.length} Chemical Waving (ids ${cwQ[0].id}–${cwQ[cwQ.length-1].id})`)
